values
(76, 35, 'Овощи и фрукты', 1.32, 'Январское меню опирается на квашеную капусту, соленые овощи, моченые яблоки, репу, корнеплоды и позднюю тыкву.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(77, 35, 'Сладости', 1.24, 'Клюква, брусника, сушеные фрукты, мед и варенье подходят для взваров, морсов, выпечки и десертов.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(78, 35, 'Рыба и морепродукты', 1.34, 'Зимой выделены судак, щука и налим для строганины, заливного и ухи.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(79, 35, 'Мясо и птица', 1.28, 'Зимний сценарий включает дичь, оленину и лосятину для горячих блюд, паштетов и томленого мяса.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(80, 36, 'Рыба и морепродукты', 1.36, 'Налим имеет зимний пик, а судак и щука подходят для ухи, заливного и строганины.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(81, 36, 'Мясо и птица', 1.30, 'Февраль еще связан с сезоном пернатой дичи и свежемороженого мяса для русской кухни.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(82, 36, 'Сладости', 1.22, 'Зимние ягоды, мед, варенье и сушеные фрукты поддерживают сбитни, чаи и начинки.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(83, 37, 'Овощи и фрукты', 1.24, 'В марте еще используются прошлогодние корнеплоды и свежие заготовки, пока запасы заканчиваются.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(84, 37, 'Рыба и морепродукты', 1.22, 'Щука до нерестового запрета подходит для расстегаев и тельного.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(85, 37, 'Бакалея', 1.16, 'Постный весенний сценарий поддерживают крупы и базовые продукты длительного хранения.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(86, 38, 'Овощи и фрукты', 1.36, 'В апреле появляются крапива, сныть, черемша и лебеда для салатов, супов и начинок.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(87, 38, 'Напитки', 1.22, 'Березовый сок отмечен как апрельская позиция для напитков и сиропов.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(88, 38, 'Рыба и морепродукты', 1.20, 'Снеток и корюшка в апреле подходят для жаркого и сезонных закусок.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(89, 39, 'Овощи и фрукты', 1.34, 'В мае в сезон входят щавель, шпинат, редис, зеленый лук и молодой картофель с южных поставок.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(90, 39, 'Яйца и молочные продукты', 1.36, 'Творог, яйца и сметана указаны как база пасхального стола.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(91, 40, 'Овощи и фрукты', 1.38, 'Июнь связан с окрошкой, редисом, зеленью, ранними овощами и первой клубникой.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(92, 40, 'Сладости', 1.26, 'Клубника подходит для десертов и вареников в начале летнего меню.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(93, 40, 'Яйца и молочные продукты', 1.18, 'Холодные летние супы и молочные блюда усиливают молочные продукты как дополняющую категорию.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(94, 41, 'Овощи и фрукты', 1.45, 'Июль выделяет грунтовые огурцы, помидоры, кабачки, молодую свеклу, морковь и зелень.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(95, 41, 'Сладости', 1.34, 'Малина, смородина, вишня, крыжовник, черника и голубика подходят для морсов, соусов, желе, пирогов и вареников.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(96, 41, 'Рыба и морепродукты', 1.18, 'Летняя речная рыба подходит для запекания и шашлыков с учетом ограничений.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(97, 42, 'Овощи и фрукты', 1.42, 'Август усиливает томаты, сладкий перец, кабачки, цукини, патиссоны, ранние яблоки и зелень.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(98, 42, 'Сладости', 1.28, 'Черника, голубика, крыжовник и ранние яблоки продолжают сценарий пирогов, десертов и соусов.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(99, 42, 'Бакалея', 1.16, 'Августовский переход к заготовкам поддерживает специи, крупы и продукты для домашней кухни.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(100, 43, 'Овощи и фрукты', 1.40, 'Сентябрь выделяет осенние яблоки, облепиху, клюкву, бруснику, рябину и основной сбор корнеплодов.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(101, 43, 'Сладости', 1.32, 'Осенние ягоды, яблоки и заготовки подходят для пастилы, выпечки, десертов, морсов и варенья.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(102, 43, 'Бакалея', 1.20, 'Грецкие орехи, фундук, тыквенные семечки и продукты для заготовок усиливают сентябрьскую витрину.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(103, 44, 'Овощи и фрукты', 1.38, 'Октябрь связан с поздней капустой, корнеплодами, яблоками, клюквой, брусникой и грибами.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(104, 44, 'Бакалея', 1.24, 'Соленья, варенья, маринады, орехи и семена поддерживают сценарий заготовок на зиму.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(105, 44, 'Сладости', 1.28, 'Яблоки, ягоды, орехи и варенье хорошо ложатся в выпечку и десертные подборки.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(106, 45, 'Мясо и птица', 1.36, 'Ноябрьское меню выделяет гуся домашнего, утку, зайца и оленя для запекания и томленых блюд.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(107, 45, 'Овощи и фрукты', 1.32, 'Тыква, поздняя капуста, яблоки и корнеплоды остаются основой ноябрьских блюд.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(108, 45, 'Сладости', 1.24, 'Орехи, семечки и яблоки поддерживают выпечку и десертные блюда поздней осени.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(109, 46, 'Овощи и фрукты', 1.34, 'Декабрь возвращает квашения, соленья, корнеплоды, моченые яблоки и позднюю тыкву.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(110, 46, 'Рыба и морепродукты', 1.36, 'Налим, судак и щука в зимнем разделе связаны с ухой, заливным и строганиной.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(111, 46, 'Мясо и птица', 1.30, 'Декабрьский сценарий включает дичь и свежемороженое мясо для горячих блюд и паштетов.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', ''),
(112, 46, 'Сладости', 1.24, 'Мед, варенье, сушеные фрукты и северные ягоды подходят для сбитней, чаев, взваров и выпечки.', 'Примеры сезонных продуктов под сезонные меню ресторанов русской кухни.docx', '');
